/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var C = [[16, 20, 0.8, 8, 6], [138, 20, 1.15, -6, -4], [16, 148, 0.95, 4, 0], [138, 148, 1.0, 0, -8]];
  phases([[0,14],[14,34],[34,56],[56,80]]);
  var s = lin([[16,0],[28,1]]), r = lin([[36,0],[44,1]]), m = lin([[46,0],[54,1]]);
  var labels = ['1:125', '1:75', '1:110', '1:100'];
  for (var i = 0; i < 4; i++) {
    var c = C[i], cx = c[0] + 56, cy = c[1] + 47;
    var sc = c[2] + (1 - c[2]) * s, rot = c[4] * (1 - r), dx = c[3] * (1 - m);
    v['vp'+i] = 'transform: translate(' + dx.toFixed(1) + 'px,0px) rotate(' + rot.toFixed(1) + 'deg) scale(' + sc.toFixed(3) + '); transform-origin: ' + cx + 'px ' + cy + 'px;';
    var ok = s > 0.95 && r > 0.95 && m > 0.95;
    v['vc'+i] = ok ? '#1E7F4F' : (i == 3 && s > 0.95 ? '#1E7F4F' : '#C0392B');
    v['st'+i] = s > 0.95 ? '1:100' : labels[i]; v['sc'+i] = s > 0.95 ? '#1E7F4F' : '#B42318';
  }
  v.k0 = p >= 28 ? out : 0.25 * out; v.k1 = p >= 44 ? out : 0.25 * out; v.k2 = p >= 54 ? out : 0.25 * out; v.k3 = p >= 60 ? out : 0.25 * out; v.k4 = p >= 66 ? out : 0.25 * out;
  v.fin = (p >= 72 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
